CREATE DATABASE IF NOT EXISTS archon_publishing CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE archon_publishing;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS activity_logs,newsletter_subscribers,contact_messages,quote_notes,quote_attachments,quote_requests,downloads,payments,order_items,orders,wishlists,cart_items,carts,coupon_uses,coupons,book_files,book_samples,book_genres,book_categories,genres,categories,reviews,blog_post_tags,blog_tags,blog_categories,blog_posts,testimonials,service_faqs,service_pages,services,password_resets,remember_tokens,email_verifications,customer_addresses,customers,admin_roles,admins,role_permissions,permissions,roles,authors,books,settings,pages,menus,menu_items,login_attempts;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE roles(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(60) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE permissions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(100) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE role_permissions(role_id BIGINT UNSIGNED NOT NULL,permission_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(role_id,permission_id),FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE,FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE);
CREATE TABLE admins(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,phone VARCHAR(80),job_title VARCHAR(120),password_hash VARCHAR(255) NOT NULL,role VARCHAR(30) NOT NULL DEFAULT 'admin',is_active TINYINT(1) NOT NULL DEFAULT 1,last_login_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(role,is_active));
CREATE TABLE admin_roles(admin_id BIGINT UNSIGNED NOT NULL,role_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(admin_id,role_id),FOREIGN KEY(admin_id) REFERENCES admins(id) ON DELETE CASCADE,FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE);
CREATE TABLE customers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,email_verified_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE customer_addresses(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,customer_id BIGINT UNSIGNED NOT NULL,label VARCHAR(40),line1 VARCHAR(190),city VARCHAR(100),country VARCHAR(100),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE CASCADE);
CREATE TABLE password_resets(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,customer_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL,expires_at DATETIME NOT NULL,used_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(token_hash),FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE CASCADE);
CREATE TABLE email_verifications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,customer_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL,expires_at DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE CASCADE);
CREATE TABLE remember_tokens(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,customer_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL,expires_at DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE CASCADE);
CREATE TABLE authors(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,bio TEXT NOT NULL,tagline VARCHAR(255),website VARCHAR(255),image_path VARCHAR(255),is_featured TINYINT(1) DEFAULT 0,is_active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE books(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,author_id BIGINT UNSIGNED NOT NULL,title VARCHAR(220) NOT NULL,slug VARCHAR(240) NOT NULL UNIQUE,subtitle VARCHAR(255),isbn VARCHAR(32) UNIQUE,short_description TEXT,description MEDIUMTEXT,price DECIMAL(10,2) NOT NULL,sale_price DECIMAL(10,2) NULL,language VARCHAR(40) DEFAULT 'English',page_count INT DEFAULT 0,rating DECIMAL(3,2) DEFAULT 0,sales_count INT DEFAULT 0,cover_path VARCHAR(255),is_featured TINYINT(1) DEFAULT 0,is_active TINYINT(1) DEFAULT 1,published_at DATE NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(author_id),INDEX(published_at),FOREIGN KEY(author_id) REFERENCES authors(id));
CREATE TABLE book_files(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,book_id BIGINT UNSIGNED NOT NULL,format ENUM('pdf','epub','mobi') NOT NULL,storage_name VARCHAR(255) NOT NULL,original_name VARCHAR(255) NOT NULL,file_size BIGINT UNSIGNED DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(book_id) REFERENCES books(id) ON DELETE CASCADE);
CREATE TABLE book_samples(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,book_id BIGINT UNSIGNED NOT NULL,storage_name VARCHAR(255) NOT NULL,original_name VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(book_id) REFERENCES books(id) ON DELETE CASCADE);
CREATE TABLE categories(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,slug VARCHAR(120) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE book_categories(book_id BIGINT UNSIGNED NOT NULL,category_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(book_id,category_id),FOREIGN KEY(book_id) REFERENCES books(id) ON DELETE CASCADE,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE CASCADE);
CREATE TABLE genres(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,slug VARCHAR(120) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE book_genres(book_id BIGINT UNSIGNED NOT NULL,genre_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(book_id,genre_id),FOREIGN KEY(book_id) REFERENCES books(id) ON DELETE CASCADE,FOREIGN KEY(genre_id) REFERENCES genres(id) ON DELETE CASCADE);
CREATE TABLE services(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,slug VARCHAR(200) NOT NULL UNIQUE,summary TEXT NOT NULL,description MEDIUMTEXT NOT NULL,benefits TEXT,timeline VARCHAR(150),starting_price DECIMAL(10,2) NULL,icon_path VARCHAR(255),display_order INT DEFAULT 0,is_active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE service_pages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,service_id BIGINT UNSIGNED NULL,kind VARCHAR(30) NOT NULL DEFAULT 'service',title VARCHAR(180),body TEXT,display_order INT DEFAULT 0,is_active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(service_id) REFERENCES services(id) ON DELETE SET NULL);
CREATE TABLE service_faqs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,service_id BIGINT UNSIGNED NOT NULL,question VARCHAR(255) NOT NULL,answer TEXT NOT NULL,display_order INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(service_id) REFERENCES services(id) ON DELETE CASCADE);
CREATE TABLE carts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,customer_id BIGINT UNSIGNED NULL,session_key VARCHAR(128) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE CASCADE);
CREATE TABLE cart_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,cart_id BIGINT UNSIGNED NOT NULL,book_id BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(cart_id,book_id),FOREIGN KEY(cart_id) REFERENCES carts(id) ON DELETE CASCADE,FOREIGN KEY(book_id) REFERENCES books(id));
CREATE TABLE coupons(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(50) NOT NULL UNIQUE,discount_type ENUM('percent','fixed') NOT NULL,discount_value DECIMAL(10,2) NOT NULL,starts_at DATETIME NULL,ends_at DATETIME NULL,max_uses INT NULL,uses_count INT DEFAULT 0,is_active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE coupon_uses(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,coupon_id BIGINT UNSIGNED NOT NULL,customer_id BIGINT UNSIGNED NOT NULL,order_id BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(coupon_id) REFERENCES coupons(id),FOREIGN KEY(customer_id) REFERENCES customers(id));
CREATE TABLE orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_number VARCHAR(40) NOT NULL UNIQUE,customer_id BIGINT UNSIGNED NOT NULL,subtotal DECIMAL(10,2) NOT NULL,discount_amount DECIMAL(10,2) DEFAULT 0,tax_amount DECIMAL(10,2) DEFAULT 0,total DECIMAL(10,2) NOT NULL,currency CHAR(3) DEFAULT 'USD',payment_status ENUM('pending','processing','paid','failed','cancelled','refunded','partially_refunded') DEFAULT 'pending',order_status ENUM('pending_payment','processing','completed','cancelled','refunded') DEFAULT 'pending_payment',payment_method VARCHAR(40) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(customer_id),FOREIGN KEY(customer_id) REFERENCES customers(id));
CREATE TABLE order_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,book_id BIGINT UNSIGNED NOT NULL,title VARCHAR(220) NOT NULL,unit_price DECIMAL(10,2) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(book_id) REFERENCES books(id));
CREATE TABLE payments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,amount DECIMAL(10,2) NOT NULL,status VARCHAR(40) NOT NULL,method VARCHAR(40) NOT NULL,reference VARCHAR(100),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE);
CREATE TABLE downloads(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_item_id BIGINT UNSIGNED NOT NULL,customer_id BIGINT UNSIGNED NOT NULL,token CHAR(32) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,max_count INT NOT NULL DEFAULT 5,download_count INT NOT NULL DEFAULT 0,last_downloaded_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_item_id) REFERENCES order_items(id) ON DELETE CASCADE,FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE CASCADE);
CREATE TABLE wishlists(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,customer_id BIGINT UNSIGNED NOT NULL,book_id BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(customer_id,book_id),FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE CASCADE,FOREIGN KEY(book_id) REFERENCES books(id) ON DELETE CASCADE);
CREATE TABLE reviews(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,customer_id BIGINT UNSIGNED NOT NULL,book_id BIGINT UNSIGNED NOT NULL,rating TINYINT UNSIGNED NOT NULL,body TEXT,status ENUM('pending','approved','rejected') DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE(customer_id,book_id),FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(book_id) REFERENCES books(id));
CREATE TABLE quote_requests(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(80),service_id BIGINT UNSIGNED NULL,book_title VARCHAR(255),genre VARCHAR(100),word_count VARCHAR(50),project_stage VARCHAR(100),completion_date DATE NULL,budget_range VARCHAR(100),description TEXT NOT NULL,status ENUM('new','contacted','in_discussion','converted','rejected','closed') DEFAULT 'new',assigned_admin_id BIGINT UNSIGNED NULL,assigned_at DATETIME NULL,lead_source VARCHAR(80) NOT NULL DEFAULT 'quote_form',priority VARCHAR(20) NOT NULL DEFAULT 'normal',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(assigned_admin_id),INDEX(status,assigned_admin_id),FOREIGN KEY(service_id) REFERENCES services(id) ON DELETE SET NULL,FOREIGN KEY(assigned_admin_id) REFERENCES admins(id) ON DELETE SET NULL);
CREATE TABLE quote_attachments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,quote_request_id BIGINT UNSIGNED NOT NULL,storage_name VARCHAR(255) NOT NULL,original_name VARCHAR(255) NOT NULL,mime_type VARCHAR(100),file_size BIGINT UNSIGNED DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(quote_request_id) REFERENCES quote_requests(id) ON DELETE CASCADE);
CREATE TABLE quote_notes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,quote_request_id BIGINT UNSIGNED NOT NULL,admin_id BIGINT UNSIGNED NULL,body TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(quote_request_id) REFERENCES quote_requests(id) ON DELETE CASCADE,FOREIGN KEY(admin_id) REFERENCES admins(id) ON DELETE SET NULL);
CREATE TABLE contact_messages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(80),subject VARCHAR(255),message TEXT NOT NULL,status ENUM('new','read','replied','archived') DEFAULT 'new',assigned_admin_id BIGINT UNSIGNED NULL,assigned_at DATETIME NULL,lead_source VARCHAR(80) NOT NULL DEFAULT 'contact_form',priority VARCHAR(20) NOT NULL DEFAULT 'normal',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(assigned_admin_id),INDEX(status,assigned_admin_id),FOREIGN KEY(assigned_admin_id) REFERENCES admins(id) ON DELETE SET NULL);
CREATE TABLE newsletter_subscribers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,unsubscribe_token CHAR(48) NOT NULL UNIQUE,status ENUM('active','unsubscribed') DEFAULT 'active',consented_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE blog_categories(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,slug VARCHAR(120) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE blog_posts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(220) NOT NULL,slug VARCHAR(240) NOT NULL UNIQUE,excerpt TEXT NOT NULL,body MEDIUMTEXT NOT NULL,status ENUM('draft','published') DEFAULT 'draft',published_at DATETIME NULL,meta_title VARCHAR(255),meta_description VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(status,published_at));
CREATE TABLE blog_tags(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,slug VARCHAR(120) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE blog_post_tags(post_id BIGINT UNSIGNED NOT NULL,tag_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(post_id,tag_id),FOREIGN KEY(post_id) REFERENCES blog_posts(id) ON DELETE CASCADE,FOREIGN KEY(tag_id) REFERENCES blog_tags(id) ON DELETE CASCADE);
CREATE TABLE testimonials(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,role VARCHAR(120),quote TEXT NOT NULL,is_active TINYINT(1) DEFAULT 1,display_order INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE settings(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,setting_key VARCHAR(100) NOT NULL UNIQUE,setting_value TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE pages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,slug VARCHAR(190) NOT NULL UNIQUE,body MEDIUMTEXT,status VARCHAR(20) DEFAULT 'published',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE menus(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE menu_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,menu_id BIGINT UNSIGNED NOT NULL,label VARCHAR(100) NOT NULL,url VARCHAR(255) NOT NULL,display_order INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(menu_id) REFERENCES menus(id) ON DELETE CASCADE);
CREATE TABLE activity_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,admin_id BIGINT UNSIGNED NULL,action VARCHAR(100) NOT NULL,entity_type VARCHAR(100),entity_id BIGINT UNSIGNED NULL,details TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(admin_id) REFERENCES admins(id) ON DELETE SET NULL);
CREATE TABLE login_attempts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190),ip_address VARCHAR(64),action VARCHAR(40),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(ip_address,created_at));
